typedef struct {
    int id;
    char name[64];
    double balance;
} Account;

Account account = { .id = 1, .name = "Sara", .balance = 1250.0 };
Account *p = &account;
printf("%s %.2f\n", p->name, p->balance);

typedef enum {
    ORDER_PENDING,
    ORDER_PAID,
    ORDER_CANCELLED
} OrderState;

typedef enum { VALUE_INT, VALUE_DOUBLE } ValueKind;

typedef struct {
    ValueKind kind;
    union {
        int as_int;
        double as_double;
    } data;
} Value;
